        return sub_arr == sub_arr[::-1]

    def count_changes(sub_arr):
        changes = 0
        for i in range(len(sub_arr) // 2):
            if sub_arr[i] != sub_arr[-i - 1]:
                changes += 1
        return changes

    min_changes = float('inf')
    for i in range(len(arr) + 1):
        left_sub_arr = arr[:i]
        right_sub_arr = arr[i:]
        changes = count_changes(left_sub_arr) + count_changes(right_sub_arr[::-1])
        min_changes = min(min_changes, changes)

    return min_changes

